begin;
set local lock_timeout = '30s';

-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 10: online booking (Calendly-like), D-043. Additive only.
-- Each staff member publishes a booking link (slug) with meeting types and weekly availability. Anyone with the link
-- (or a client in the portal) requests a free slot; the consultant approves it, which creates the CRM meeting (Gate 9).
-- The public side never touches the database directly: the server calls the service_role-only functions below after
-- validating input, and every rule (window, notice, horizon, overlap, rate limit) is re-checked here.

create table cw_prod.booking_profiles (
  user_id            uuid primary key references cw_prod.profiles (id) on delete cascade,
  slug               text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'),
  active             boolean not null default false,
  headline           text check (length(headline) <= 300),
  min_notice_minutes integer not null default 240 check (min_notice_minutes between 0 and 20160),
  horizon_days       integer not null default 30 check (horizon_days between 1 and 90),
  buffer_minutes     integer not null default 0 check (buffer_minutes between 0 and 120),
  updated_at         timestamptz not null default now()
);

create table cw_prod.booking_types (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references cw_prod.profiles (id) on delete cascade,
  name             text not null check (length(name) between 1 and 80),
  duration_minutes integer not null check (duration_minutes in (15, 30, 45, 60, 90, 120)),
  description      text check (length(description) <= 500),
  location_kind    text not null check (location_kind in ('ONLINE', 'IN_PERSON', 'PHONE')),
  location_detail  text check (length(location_detail) <= 300),
  active           boolean not null default true,
  created_at       timestamptz not null default now()
);
create index on cw_prod.booking_types (user_id);

-- Weekly availability in Brasília local minutes (ISO weekday: 1 = Monday … 7 = Sunday).
create table cw_prod.booking_windows (
  id        uuid primary key default gen_random_uuid(),
  user_id   uuid not null references cw_prod.profiles (id) on delete cascade,
  weekday   smallint not null check (weekday between 1 and 7),
  start_min integer not null check (start_min between 0 and 1425 and start_min % 15 = 0),
  end_min   integer not null check (end_min between 15 and 1440 and end_min % 15 = 0),
  check (end_min > start_min)
);
create index on cw_prod.booking_windows (user_id, weekday);

create table cw_prod.booking_requests (
  id             uuid primary key default gen_random_uuid(),   -- also the idempotency key of the CRM meeting
  owner_id       uuid not null references cw_prod.profiles (id) on delete cascade,
  type_id        uuid not null references cw_prod.booking_types (id),
  starts_at      timestamptz not null,
  ends_at        timestamptz not null,
  name           text not null check (length(name) between 2 and 120),
  email          text not null check (email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' and length(email) <= 254),
  phone          text check (phone ~ '^[0-9]{10,13}$'),
  notes          text check (length(notes) <= 1000),
  source         text not null check (source in ('PUBLIC', 'PORTAL')),
  client_id      uuid references cw_prod.clients (id) on delete set null,
  contact_id     uuid references cw_prod.crm_contacts (id) on delete set null,
  event_id       uuid references cw_prod.crm_events (id) on delete set null,
  status         text not null default 'PENDING' check (status in ('PENDING', 'CONFIRMED', 'DECLINED')),
  decline_reason text check (length(decline_reason) <= 300),
  requester_hash text check (requester_hash ~ '^[0-9a-f]{64}$'),   -- sha256 of the requester network address
  created_at     timestamptz not null default now(),
  decided_at     timestamptz,
  check (ends_at > starts_at),
  check (status <> 'CONFIRMED' or event_id is not null)
);
create index on cw_prod.booking_requests (owner_id, starts_at);
create index on cw_prod.booking_requests (owner_id, lower(email)) where status = 'PENDING';
create index on cw_prod.booking_requests (requester_hash, created_at);

alter table cw_prod.booking_profiles enable row level security, force row level security;
alter table cw_prod.booking_types    enable row level security, force row level security;
alter table cw_prod.booking_windows  enable row level security, force row level security;
alter table cw_prod.booking_requests enable row level security, force row level security;
revoke all on cw_prod.booking_profiles, cw_prod.booking_types, cw_prod.booking_windows, cw_prod.booking_requests
  from public, anon, authenticated;

create trigger t_audit after insert or update or delete on cw_prod.booking_requests for each row execute function cw_prod_private.audit_row();

-- Staff read their own configuration and requests; all writes go through the functions below.
create policy booking_profiles_read on cw_prod.booking_profiles for select to authenticated
  using (user_id = (select auth.uid()) and (select cw_prod_private.is_staff()));
create policy booking_types_read on cw_prod.booking_types for select to authenticated
  using (user_id = (select auth.uid()) and (select cw_prod_private.is_staff()));
create policy booking_windows_read on cw_prod.booking_windows for select to authenticated
  using (user_id = (select auth.uid()) and (select cw_prod_private.is_staff()));
create policy booking_requests_read on cw_prod.booking_requests for select to authenticated
  using (owner_id = (select auth.uid()) and (select cw_prod_private.is_staff()));
grant select on cw_prod.booking_profiles, cw_prod.booking_types, cw_prod.booking_windows to authenticated;
grant select (id, owner_id, type_id, starts_at, ends_at, name, email, phone, notes, source, client_id, contact_id, event_id,
              status, decline_reason, created_at, decided_at) on cw_prod.booking_requests to authenticated;
grant all on cw_prod.booking_profiles, cw_prod.booking_types, cw_prod.booking_windows, cw_prod.booking_requests to service_role;

-- ---------------------------------------------------------------- consultant configuration
create function cw_prod.booking_profile_save(p_slug text, p_active boolean, p_headline text, p_notice integer,
                                           p_horizon integer, p_buffer integer) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  insert into cw_prod.booking_profiles as b (user_id, slug, active, headline, min_notice_minutes, horizon_days, buffer_minutes)
  values (auth.uid(), lower(btrim(p_slug)), coalesce(p_active, false), nullif(btrim(p_headline), ''), p_notice, p_horizon, p_buffer)
  on conflict (user_id) do update
    set slug = excluded.slug, active = excluded.active, headline = excluded.headline, min_notice_minutes = excluded.min_notice_minutes,
        horizon_days = excluded.horizon_days, buffer_minutes = excluded.buffer_minutes, updated_at = now();
end $$;

-- Replaces the caller's weekly availability. p_windows: [{"weekday":1,"start":540,"end":720}, ...]
create function cw_prod.booking_windows_set(p_windows jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  if jsonb_typeof(p_windows) <> 'array' or jsonb_array_length(p_windows) > 42 then raise exception 'invalid windows' using errcode = '22023'; end if;
  delete from cw_prod.booking_windows where user_id = auth.uid();
  insert into cw_prod.booking_windows (user_id, weekday, start_min, end_min)
  select auth.uid(), (w ->> 'weekday')::smallint, (w ->> 'start')::integer, (w ->> 'end')::integer
    from jsonb_array_elements(p_windows) w;
  if exists (select 1 from cw_prod.booking_windows a join cw_prod.booking_windows b
               on a.user_id = b.user_id and a.weekday = b.weekday and a.id < b.id
              and a.start_min < b.end_min and b.start_min < a.end_min
              where a.user_id = auth.uid()) then
    raise exception 'overlapping windows' using errcode = '22023';
  end if;
end $$;

create function cw_prod.booking_type_save(p_id uuid, p_name text, p_duration integer, p_description text, p_location_kind text,
                                        p_location_detail text, p_active boolean) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  if p_id is null then
    insert into cw_prod.booking_types (user_id, name, duration_minutes, description, location_kind, location_detail, active)
    values (auth.uid(), btrim(p_name), p_duration, nullif(btrim(p_description), ''), p_location_kind, nullif(btrim(p_location_detail), ''), coalesce(p_active, true))
    returning id into v_id;
  else
    update cw_prod.booking_types
       set name = btrim(p_name), duration_minutes = p_duration, description = nullif(btrim(p_description), ''),
           location_kind = p_location_kind, location_detail = nullif(btrim(p_location_detail), ''), active = coalesce(p_active, true)
     where id = p_id and user_id = auth.uid()
    returning id into v_id;
    if v_id is null then perform cw_prod_private.deny(); end if;
  end if;
  return v_id;
end $$;

-- ---------------------------------------------------------------- consultant decisions
create function cw_prod.booking_request_decline(p_id uuid, p_reason text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  update cw_prod.booking_requests set status = 'DECLINED', decline_reason = nullif(left(btrim(p_reason), 300), ''), decided_at = now()
   where id = p_id and owner_id = auth.uid() and status = 'PENDING';
  if not found then perform cw_prod_private.deny(); end if;
end $$;

-- Called after the server created the CRM meeting (idempotency key = request id) for this request.
create function cw_prod.booking_request_confirm(p_id uuid, p_event uuid, p_contact uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare r cw_prod.booking_requests;
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  select * into r from cw_prod.booking_requests where id = p_id and owner_id = auth.uid() for update;
  if not found then perform cw_prod_private.deny(); end if;
  if r.status = 'CONFIRMED' and r.event_id = p_event then return; end if;   -- idempotent retry
  if r.status <> 'PENDING' or not exists (
       select 1 from cw_prod.crm_events e where e.id = p_event and e.owner_id = auth.uid() and e.contact_id = p_contact
          and e.idempotency_key = p_id and e.starts_at = r.starts_at and e.ends_at = r.ends_at) then
    perform cw_prod_private.deny();
  end if;
  update cw_prod.booking_requests set status = 'CONFIRMED', event_id = p_event, contact_id = p_contact, decided_at = now() where id = p_id;
end $$;

-- Consultants assigned to the signed-in client who accept online booking (client portal).
create function cw_prod.my_booking_consultants() returns table (slug text, full_name text)
language sql stable security definer set search_path = '' as $$
  select b.slug, p.full_name
    from cw_prod.client_users cu
    join cw_prod.consultant_client_access a on a.client_id = cu.client_id and a.status = 'ACTIVE'
    join cw_prod.booking_profiles b on b.user_id = a.consultant_id and b.active
    join cw_prod.profiles p on p.id = a.consultant_id and p.status = 'ACTIVE'
   where cu.user_id = auth.uid() and cw_prod_private.my_role() = 'CLIENT' and cw_prod_private.can_access_client(cu.client_id)
   order by p.full_name
$$;

-- ---------------------------------------------------------------- public side (service_role only)
create function cw_prod.booking_public_page(p_slug text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'owner_name', p.full_name, 'headline', b.headline, 'notice', b.min_notice_minutes, 'horizon', b.horizon_days, 'buffer', b.buffer_minutes,
    'types', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'duration', t.duration_minutes, 'description', t.description,
                                                           'location_kind', t.location_kind) order by t.duration_minutes, t.name)
                         from cw_prod.booking_types t where t.user_id = b.user_id and t.active), '[]'::jsonb),
    'windows', coalesce((select jsonb_agg(jsonb_build_object('weekday', w.weekday, 'start', w.start_min, 'end', w.end_min) order by w.weekday, w.start_min)
                           from cw_prod.booking_windows w where w.user_id = b.user_id), '[]'::jsonb))
    from cw_prod.booking_profiles b join cw_prod.profiles p on p.id = b.user_id and p.status = 'ACTIVE'
   where b.slug = lower(p_slug) and b.active
$$;

-- Busy intervals only (no titles, no people): scheduled CRM meetings and pending requests of the link owner.
create function cw_prod.booking_public_busy(p_slug text, p_from timestamptz, p_to timestamptz)
returns table (starts_at timestamptz, ends_at timestamptz)
language sql stable security definer set search_path = '' as $$
  select e.starts_at, e.ends_at from cw_prod.crm_events e join cw_prod.booking_profiles b on b.user_id = e.owner_id
   where b.slug = lower(p_slug) and b.active and e.status = 'SCHEDULED' and e.starts_at < p_to and e.ends_at > p_from
  union all
  select r.starts_at, r.ends_at from cw_prod.booking_requests r join cw_prod.booking_profiles b on b.user_id = r.owner_id
   where b.slug = lower(p_slug) and b.active and r.status = 'PENDING' and r.starts_at < p_to and r.ends_at > p_from
$$;

-- Google refresh token of the link owner, so the server can hide slots taken by personal Google events.
create function cw_prod.booking_owner_google_token(p_slug text) returns text
language plpgsql stable security definer set search_path = '' as $$
declare v_secret uuid; v_token text;
begin
  select c.vault_secret_id into v_secret from cw_prod.calendar_connections c join cw_prod.booking_profiles b on b.user_id = c.user_id
   where b.slug = lower(p_slug) and b.active and c.provider = 'GOOGLE' and c.status = 'CONNECTED';
  if v_secret is null then return null; end if;
  select decrypted_secret into v_token from vault.decrypted_secrets where id = v_secret;
  return v_token;
end $$;

create function cw_prod.booking_request_create(p_slug text, p_type uuid, p_starts timestamptz, p_name text, p_email text,
                                             p_phone text, p_notes text, p_client uuid, p_hash text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare b cw_prod.booking_profiles; t cw_prod.booking_types; v_end timestamptz; v_local timestamp; v_min integer; v_id uuid;
begin
  select * into b from cw_prod.booking_profiles where slug = lower(p_slug) and active for update;   -- serializes requests per link
  if not found then raise exception 'booking unavailable' using errcode = 'P0002'; end if;
  select * into t from cw_prod.booking_types where id = p_type and user_id = b.user_id and active;
  if not found then raise exception 'booking unavailable' using errcode = 'P0002'; end if;
  v_end := p_starts + make_interval(mins => t.duration_minutes);
  v_local := p_starts at time zone 'America/Sao_Paulo';
  v_min := extract(hour from v_local)::integer * 60 + extract(minute from v_local)::integer;
  if extract(second from v_local) <> 0 or v_min % 15 <> 0 or v_min + t.duration_minutes > 1440
     or p_starts < now() + make_interval(mins => b.min_notice_minutes) or p_starts > now() + make_interval(days => b.horizon_days)
     or not exists (select 1 from cw_prod.booking_windows w where w.user_id = b.user_id and w.weekday = extract(isodow from v_local)
                       and w.start_min <= v_min and w.end_min >= v_min + t.duration_minutes) then
    raise exception 'slot not offered' using errcode = '22023';
  end if;
  if exists (select 1 from cw_prod.crm_events e where e.owner_id = b.user_id and e.status = 'SCHEDULED'
                and e.starts_at < v_end + make_interval(mins => b.buffer_minutes) and e.ends_at > p_starts - make_interval(mins => b.buffer_minutes))
     or exists (select 1 from cw_prod.booking_requests r where r.owner_id = b.user_id and r.status = 'PENDING'
                and r.starts_at < v_end + make_interval(mins => b.buffer_minutes) and r.ends_at > p_starts - make_interval(mins => b.buffer_minutes)) then
    raise exception 'slot taken' using errcode = '23P01';
  end if;
  if (select count(*) from cw_prod.booking_requests where owner_id = b.user_id and lower(email) = lower(btrim(p_email)) and status = 'PENDING') >= 3
     or (p_hash is not null and (select count(*) from cw_prod.booking_requests where requester_hash = p_hash and created_at > now() - interval '1 day') >= 10) then
    raise exception 'rate limited' using errcode = '53400';
  end if;
  if p_client is not null and not exists (select 1 from cw_prod.consultant_client_access a
                                          where a.consultant_id = b.user_id and a.client_id = p_client and a.status = 'ACTIVE') then
    raise exception 'booking unavailable' using errcode = 'P0002';
  end if;
  insert into cw_prod.booking_requests (owner_id, type_id, starts_at, ends_at, name, email, phone, notes, source, client_id, requester_hash)
  values (b.user_id, t.id, p_starts, v_end, btrim(p_name), lower(btrim(p_email)), nullif(p_phone, ''), nullif(btrim(p_notes), ''),
          case when p_client is null then 'PUBLIC' else 'PORTAL' end, p_client, p_hash)
  returning id into v_id;
  return v_id;
end $$;

-- Status page of one request (the id is the unguessable reference shown to the requester). No personal data.
create function cw_prod.booking_public_request(p_id uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('status', r.status, 'starts_at', r.starts_at, 'ends_at', r.ends_at, 'type', t.name,
                            'location_kind', t.location_kind, 'owner_name', p.full_name, 'slug', b.slug)
    from cw_prod.booking_requests r join cw_prod.booking_types t on t.id = r.type_id join cw_prod.profiles p on p.id = r.owner_id
    left join cw_prod.booking_profiles b on b.user_id = r.owner_id
   where r.id = p_id
$$;

revoke all on function
  cw_prod.booking_profile_save(text, boolean, text, integer, integer, integer), cw_prod.booking_windows_set(jsonb),
  cw_prod.booking_type_save(uuid, text, integer, text, text, text, boolean), cw_prod.booking_request_decline(uuid, text),
  cw_prod.booking_request_confirm(uuid, uuid, uuid), cw_prod.my_booking_consultants(),
  cw_prod.booking_public_page(text), cw_prod.booking_public_busy(text, timestamptz, timestamptz), cw_prod.booking_owner_google_token(text),
  cw_prod.booking_request_create(text, uuid, timestamptz, text, text, text, text, uuid, text), cw_prod.booking_public_request(uuid)
  from public, anon, authenticated;
grant execute on function
  cw_prod.booking_profile_save(text, boolean, text, integer, integer, integer), cw_prod.booking_windows_set(jsonb),
  cw_prod.booking_type_save(uuid, text, integer, text, text, text, boolean), cw_prod.booking_request_decline(uuid, text),
  cw_prod.booking_request_confirm(uuid, uuid, uuid), cw_prod.my_booking_consultants() to authenticated;
grant execute on function
  cw_prod.booking_public_page(text), cw_prod.booking_public_busy(text, timestamptz, timestamptz), cw_prod.booking_owner_google_token(text),
  cw_prod.booking_request_create(text, uuid, timestamptz, text, text, text, text, uuid, text), cw_prod.booking_public_request(uuid) to service_role;

commit;

select c.relname, c.relrowsecurity and c.relforcerowsecurity as rls_forcado from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='cw_prod' and c.relname like 'booking_%' and c.relkind='r' order by 1;
